using SeleneFrontend.Models;

namespace SeleneFrontend.Services;

/// <summary>
/// <c>illumination/{siteId}/heights.json</c> (generated by <c>pipeline/build_heights.py</c>, additive and optional):
/// the site's horizon mask for several observer heights above the terrain. The hourly series use 2 m.
/// </summary>
public sealed class HorizonHeightsData
{
    public string SiteId { get; set; } = "";
    public double SeriesObserverHeightM { get; set; } = 2;
    public List<HorizonAtHeight> Heights { get; set; } = [];

    public HorizonAtHeight? At(double heightM) => Heights.FirstOrDefault(h => Math.Abs(h.HeightM - heightM) < 1e-6);
}

public sealed class HorizonAtHeight
{
    public double HeightM { get; set; }
    /// <summary>Share of all hours in the data with any Sun (%), like <c>index.json → pctSunlit</c>.</summary>
    public double PctSunlit { get; set; }
    public double PctComms { get; set; }
    public int[] HorizonCentiDeg { get; set; } = [];
}

/// <summary>The shown mission with the panels and antenna at another height above the ground.</summary>
public sealed record HeightCase(double HeightM, Verdict Verdict, double MinSocPct, double SunPct, double CommsPct);

/// <summary>Does the verdict hold if the panels sit lower or higher than the model's 2 m?</summary>
public sealed record PanelHeightSensitivity(double NominalHeightM, Verdict Nominal, double NominalSunPct, HeightCase Low, HeightCase High)
{
    public bool Robust => Low.Verdict == Nominal && High.Verdict == Nominal;
}

/// <summary>
/// Panel-height sensitivity. On summits and rims a few metres change how much terrain blocks the Sun and the Earth
/// (pipeline/README.md → panel height). The hourly series assume 2 m; landers carry panels roughly 1–3 m above
/// the ground, so the mission is re-run with the site's horizon for 1 m and 3 m (same date, duration and heading).
/// Pure logic, no UI (linked into SeleneFrontend.Tests); reuses the ellipse's horizon swap.
/// </summary>
public static class PanelHeightAnalysis
{
    public const double LowM = 1;
    public const double HighM = 3;

    public static PanelHeightSensitivity? For(IlluminationSeries site, HorizonHeightsData data, LanderInputs lander,
                                              SimulationResult nominal, MissionThresholds thresholds,
                                              double lowM = LowM, double highM = HighM)
    {
        if (data.At(lowM) is not { } low || data.At(highM) is not { } high) return null;
        if (!site.HasSunGeometry || !site.HasEarthElevation || site.EarthAzCentiDeg.Length < site.Count) return null;
        var start = site.IndexOf(nominal.LandingUtc);
        if (start < 0 || start + nominal.Steps > site.Count) return null;
        var pinned = lander with { HeadingDeg = nominal.HeadingDeg ?? lander.HeadingDeg };

        HeightCase Run(HorizonAtHeight h)
        {
            var point = new EllipsePoint { HorizonCentiDeg = h.HorizonCentiDeg };      // same place, other mask
            var series = LandingEllipse.PointSeries(site, point, start, nominal.Steps);
            var r = MissionSimulator.Run(series, pinned, series.Start, nominal.DurationDays, thresholds, recordSeries: false);
            return new HeightCase(h.HeightM, r.Verdict, r.MinSocPct, r.SunPct, r.CommsPct);
        }

        return new PanelHeightSensitivity(data.SeriesObserverHeightM, nominal.Verdict, nominal.SunPct, Run(low), Run(high));
    }
}
